const { visibleFields } = useFormSchema(meta, form, {
  presets,
  locale,
  converters,
});

<Form form={form} initialValues={meta.initialValues} layout="vertical">
  {visibleFields.map((field) => (
    <Form.Item
      key={field.key}
      {...field.itemProps}
      label={field.label}
      required={field.required}
    >
      {field.control}
    </Form.Item>
  ))}
</Form>;
